-- ...and so does `ALTER TABLE ... ALTER COLUMN ... ADD GENERATED ... AS IDENTITY`,
-- the form pg_dump emits.
-- @setup
CREATE TABLE addident (x INT NOT NULL);
CREATE SEQUENCE addident_x_seq START WITH 500;
ALTER TABLE addident ALTER COLUMN x ADD GENERATED BY DEFAULT AS IDENTITY;
INSERT INTO addident (x) VALUES (DEFAULT);
-- @test
SELECT x FROM addident;
